class Solution {
  public int minDays(int n) {
    int INF = Integer.MAX_VALUE / 2;
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = -1;
    for (int s = 1; s <= n; s++) {
      for (int len = 1; len * (len + 1) / 2 <= s; len++) {
        int prev = dp[s - len * (len + 1) / 2];
        if (prev < INF) dp[s] = Math.min(dp[s], prev + len + 1);
      }
    }
    return dp[n];
  }
}
